      "name": "Finset.prod_antidiagonal_pow_choose_succ",
      "type": " {M : Type u_2} [CommMonoid M] (f : ℕ → ℕ → M) (n : ℕ) : ∏ ij ∈ Finset.HasAntidiagonal.antidiagonal (n + 1), f ij.1 ij.2 ^ (n + 1).choose ij.1 = (∏ ij ∈ Finset.HasAntidiagonal.antidiagonal n, f ij.1 (ij.2 + 1) ^ n.choose ij.1) * ∏ ij ∈ Finset.HasAntidiagonal.antidiagonal n, f (ij.1 + 1) ij.2 ^ n.choose ij.2",
      "module": "Mathlib.Data.Nat.Choose.Sum"
    },
    {
      "name": "Finset.prod_pow_choose_succ",
      "type": " {M : Type u_2} [CommMonoid M] (f : ℕ → ℕ → M) (n : ℕ) : ∏ i ∈ Finset.range (n + 2), f i (n + 1 - i) ^ (n + 1).choose i = (∏ i ∈ Finset.range (n + 1), f i (n + 1 - i) ^ n.choose i) * ∏ i ∈ Finset.range (n + 1), f (i + 1) (n - i) ^ n.choose i",
      "module": "Mathlib.Data.Nat.Choose.Sum"
    },
    {
      "name": "Nat.prod_pow_factorization_choose",
      "type": " (n k : ℕ) (hkn : k ≤ n) : ∏ p ∈ Finset.range (n + 1), p ^ (n.choose k).factorization p = n.choose k",
      "module": "Mathlib.Data.Nat.Choose.Factorization"
    },
    {
      "name": "Finset.prod_powersetCard",
      "type": " {α : Type u_1} {β : Type u_2} [CommMonoid β] (n : ℕ) (s : Finset α) (f : ℕ → β) : ∏ t ∈ Finset.powersetCard n s, f t.card = f n ^ s.card.choose n",
      "module": "Mathlib.Algebra.BigOperators.Group.Finset.Powerset"
    },
    {
      "name": "Nat.uniformBell_eq",
      "type": " (m n : ℕ) : m.uniformBell n = ∏ p ∈ Finset.range m, (p * n + n - 1).choose (n - 1)",
      "module": "Mathlib.Combinatorics.Enumerative.Bell"
    },
    {
      "name": "Choose.choose_modEq_prod_range_choose_nat",
      "type": " {n k p : ℕ} [Fact (Nat.Prime p)] {a : ℕ} (ha₁ : n < p ^ a) (ha₂ : k < p ^ a) : n.choose k ≡ ∏ i ∈ Finset.range a, (n / p ^ i % p).choose (k / p ^ i % p) [MOD p]",
